import{_ as s,l as n,o as a,c as i,v as o,p,x as r,d as l,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"Zab 与 ZooKeeper","description":"","frontmatter":{"title":"Zab 与 ZooKeeper","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/zab-zookeeper.md","filePath":"cs/zab-zookeeper.md","lastUpdated":1789023840000}'),h={name:"cs/zab-zookeeper.md"};function A(E,e,b,Z,f,u){const t=n("Mermaid");return a(),i("div",null,[e[1]||(e[1]=o('<h1 id="zab-与-zookeeper" tabindex="-1">Zab 与 ZooKeeper <a class="header-anchor" href="#zab-与-zookeeper" aria-label="Permalink to &quot;Zab 与 ZooKeeper&quot;">​</a></h1><div class="epigraph"><p>Zab 给前缀一致的广播：同一纪元里领导者的事务全序，切换纪元时新主对齐已提交前缀。ZooKeeper 用它实现文件系统 API 的线性一致元数据。</p><footer>—— 据 Hunt, Konar, Junqueira and Reed, ZooKeeper, USENIX ATC 2010；Junqueira, Reed and Serafini, Zab, DSN 2011 整理</footer></div><p>上一课<a href="/cs/raft-membership-snapshot">Raft 成员与快照</a>讲了日志上的配置。缺口是<strong>另一条被广泛跑的日志协议</strong>：ZooKeeper 不是 Raft 实现，它用 Zab。本课对照 RSM 形状，不重写 Raft 投票。后课 VR 更早，是第三条亲戚。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Zab 保证：已交付的事务形成全序；新领导者恢复时，已提交前缀不丢、未达多数派的尾可丢。纪元（epoch）类似 term。发现与同步阶段选出领导者并补齐跟随者，广播阶段流水线事务。ZXID 高位纪元、低位计数，比较规则钉「更新的日志」。</p><p>ZooKeeper API：znode、watch、顺序节点。客户端会话带<a href="/cs/leases">租约</a>式超时。写走领导者，读可走跟随者——默认读不是线性一致，<code>sync</code> 后读才追上。这是<a href="/cs/session-guarantees">会话</a>与 RSM 的交界：产品把弱读当默认。</p><p><span class="marginnote">ATC 2010 讲服务；DSN 2011 讲 Zab。Chubby 用 Paxos，下一课再钉锁服务对照。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写：领导者赋 ZXID，多数派持久后交付状态机。watch：对 znode 的一次性回调，不是总线级可靠订阅——丢失要靠版本再读。成员：集成在 ZooKeeper 自身，配置也是 znode 树的一部分加法定人数。</p>',9)),(a(),p(c,null,{default:r(()=>[d(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20LD%5B%22%E9%A2%86%E5%AF%BC%E8%80%85%E5%B9%BF%E6%92%AD%22%5D%20--%3E%20ZX%5B%22ZXID%20%E5%85%A8%E5%BA%8F%22%5D%0A%20%20ZX%20--%3E%20MAJ%5B%22%E5%A4%9A%E6%95%B0%E6%B4%BE%E6%8C%81%E4%B9%85%22%5D%0A%20%20MAJ%20--%3E%20DELIV%5B%22%E4%BA%A4%E4%BB%98%22%5D%0A%20%20EP%5B%22%E6%96%B0%E7%BA%AA%E5%85%83%E5%90%8C%E6%AD%A5%22%5D%20--%3E%20PREF%5B%22%E5%AF%B9%E9%BD%90%E5%B7%B2%E6%8F%90%E4%BA%A4%E5%89%8D%E7%BC%80%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>与 Raft：都是稳定主日志。Zab 强调广播原语的前缀性质；Raft 强调可理解的状态机与日志匹配。不要把二者当互为形式化翻译而不看提交规则差异。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>线性一致写：多数派 ack。线性一致读：读领导者或 sync。Chubby 风格的锁在 ZK 上用临时顺序节点实现——那是后课锁与 fencing 的例子，本课只指出 API 能做。脑裂：旧领导者纪元落后，写被拒。</p><p>本课不把 Kafka 早期「用 ZK 做控制器」当成 Zab 本身；那是客户端。也不把 ZK 当 CAP 的 AP 系统：它是 CP 元数据。</p><p>快照与滚动：ZK 有快照+事务日志，与 Raft 快照同族工程税。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 watch 的所有边角、不引入 Zxid 溢出。后课默认：说到 ZK，日志是 Zab，读默认可旧，写走多数派。VR 下一课说明这些「主+日志」比 Paxos 论文更早出现在 Liskov 组。</p><p>前缀广播是 RSM 的投递层。API 把弱读暴露出去，不改变写路径的全序。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Zab：纪元 + ZXID 前缀一致广播。</li><li>ZooKeeper 写线性一致；跟随者读默认可旧。</li><li>与 Raft 同族不同提交与恢复术语。</li><li>出处：Hunt et al., ATC 2010；Junqueira et al., DSN 2011。</li></ul>',10))])}const m=s(h,[["render",A]]);export{B as __pageData,m as default};
